// Glosar: Wareneinsatz = costul mărfii · bleibt dir pro Stück = îți rămâne pe bucată · Müll = gunoi · Kühlstelle = punct de răcire
// Rundgang = rundă de verificare · Inventur = inventar · Putzplan = plan de curățenie · Beleg = bon · Umsatz = încasări · Zähler = contor
// Einrichtung = configurare · Laden = local · Gericht = preparat · Rezept = rețetă · Speisekarte = meniu · Personalessen = masa personalului
// Plural: 1 zi / 2–19 zile / 20+ de zile
const de = (n) => { const x = Math.abs(Number(n)); if (!Number.isInteger(x) || x === 0) return ""; const h = x % 100; return h === 0 || h >= 20 ? "de " : ""; };
const nr = (n, unu, multe) => Number(n) === 1 ? `1 ${unu}` : `${n} ${de(n)}${multe}`;

